/* Prototipo local. Sin integración con almacenamiento de BOTÍN.EXE 1.2. */
(()=>{'use strict';
 const C=window.BotinCore,$=id=>document.getElementById(id),KEY='botin-workbench-prototype-v1';
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const types={item:'Objeto',spell:'Conjuro',rule:'Regla',feat:'Dote',background:'Trasfondo',species:'Especie / linaje',class:'Clase',subclass:'Subclase'};
 const labels={market:['Mercado','Consultá existencias, armá una compra o averiguá cuánto lleva fabricar.'],loot:['Loot','Una recompensa para la mesa, usando la misma biblioteca.'],craft:['Crafteo','Requisitos, materiales y tiempo. La entrega la resolvés vos.'],library:['Biblioteca','Una ficha compartida para cada objeto, conjuro y regla.'],spells:['Conjuros','Buscá efectos y consultá la referencia sin salir de la mesa.'],rules:['Reglas','Las reglas a mano, con su procedencia visible.'],homebrew:['Homebrew','Creá, adaptá y elegí en qué campañas estará disponible.'],campaigns:['Campañas','La base es compartida. Cada mesa elige qué usa.']};
 let db=C.initial(),blocked=false,view='market',query='',filter='all',page=0,selected=null,merchantId='general',craftId=null,craftMerchant='general',craftQty=1,lootCount=3,toastTimer;
 try{const raw=localStorage.getItem(KEY);if(raw)db=C.validate(JSON.parse(raw));}catch(e){blocked=true;}
 const all=()=>[...window.SRD_DATA,...db.entries];
 const available=()=>C.effective(all(),db.campaign,db.disabled);
 const visibleMerchants=()=>db.merchants.filter(m=>C.visible(m,db.campaign));
 const entry=id=>all().find(e=>e.id===id);
 const merchant=id=>db.merchants.find(m=>m.id===id);
 function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,5000);}
 function save(){if(blocked){$('save-status').textContent='Lectura fallida · datos previos protegidos';return false;}try{localStorage.setItem(KEY,JSON.stringify(db));$('save-status').textContent='● Guardado en este navegador';return true;}catch(e){$('save-status').textContent='⚠ Sin guardado persistente';toast('No se pudo guardar. Exportá un respaldo antes de cerrar.');return false;}}
 function download(name,body){const url=URL.createObjectURL(new Blob([body],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 function campaignOptions(current){return db.campaigns.map(c=>`<option value="${esc(c.id)}" ${c.id===current?'selected':''}>${esc(c.name)}</option>`).join('');}
 function merchantOptions(current){return visibleMerchants().map(m=>`<option value="${esc(m.id)}" ${m.id===current?'selected':''}>${esc(m.name)}</option>`).join('');}
 function shop(){const key=db.campaign+'|'+merchantId;return db.shops[key]||(db.shops[key]={mode:'manual',floor:0,stock:{},cart:[],discount:0});}
 function marketItems(){const m=merchant(merchantId);return available().filter(e=>e.type==='item'&&(m.id==='general'||m.categories.includes(e.category)));}
 const cartLines=()=>shop().cart.filter(l=>marketItems().some(e=>e.id===l.id));
 const fits=e=>(filter==='all'||e.category===filter||e.type===filter)&&C.norm(e.name+' '+(e.english||'')+' '+e.description+' '+e.category).includes(C.norm(query));
 function pagination(count){const pages=Math.max(1,Math.ceil(count/18));page=Math.min(page,pages-1);return `<div class="pagination"><button data-action="prev" ${page===0?'disabled':''}>← Anterior</button><span>${page+1} / ${pages} · ${count} fichas</span><button data-action="next" ${page>=pages-1?'disabled':''}>Siguiente →</button></div>`;}
 function sourceNotice(){return '<div class="notice">Prototipo de flujos · extractos SRD en inglés, con algunos nombres traducidos para búsqueda. Catálogo y traducción pendientes de cotejo completo.</div>';}
 function render(){
  if(!visibleMerchants().some(m=>m.id===merchantId))merchantId=visibleMerchants()[0]?.id||'general';
  if(!visibleMerchants().some(m=>m.id===craftMerchant))craftMerchant=merchantId;
  $('campaign').innerHTML=campaignOptions(db.campaign);$('breadcrumb').textContent=labels[view][0];$('title').innerHTML=esc(labels[view][0])+'<span class="cursor">_</span>';$('subtitle').textContent=labels[view][1];
  document.querySelectorAll('[data-view]').forEach(b=>{if(b.dataset.view===view)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});
  $('create').textContent=view==='market'?'＋ Agregar comerciante':view==='campaigns'?'＋ Nueva campaña':'＋ Crear contenido';
  if(view==='market')renderMarket();else if(view==='craft')renderCraft();else if(view==='loot')renderLoot();else if(view==='campaigns')renderCampaigns();else renderLibrary();
 }
 function navigate(next){view=labels[next]?next:'market';query='';filter='all';page=0;selected=null;history.replaceState(null,'','#'+view);render();}
 function renderMarket(){
  const s=shop(),m=merchant(merchantId),items=marketItems();
  $('view').innerHTML=`<div class="summary"><div><small>COMERCIANTE</small><strong class="small-value">${esc(m.name)}</strong></div><div><small>CATÁLOGO ACCESIBLE</small><strong>${items.length} <span class="muted small">objetos</span></strong></div><div><small>DISPONIBILIDAD</small><strong class="small-value">${s.mode==='manual'?'Decide el DM':'Stock sorteado'}</strong></div></div><div class="split"><section class="panel"><div class="panel-head"><h2>Mostrador</h2><span class="tag">${esc(db.campaigns.find(c=>c.id===db.campaign).name)}</span></div><div class="toolbar"><select id="merchant" aria-label="Comerciante">${merchantOptions(merchantId)}</select><input id="search" type="search" placeholder="Buscar objeto o atributo…" aria-label="Buscar objetos" value="${esc(query)}"></div><div class="toolbar"><label>Disponibilidad<select id="stock-mode"><option value="manual" ${s.mode==='manual'?'selected':''}>Decide el DM</option><option value="random" ${s.mode==='random'?'selected':''}>Stock aleatorio</option></select></label><label>Mínimo por objeto<input id="stock-floor" type="number" min="0" max="100" value="${s.floor}" style="width:110px"></label><button data-action="restock">↻ Renovar stock</button></div><div id="results"></div></section><aside><section class="panel"><div class="panel-head"><h2>Compra de la mesa</h2><span class="tag">PO</span></div><div id="cart"></div></section><section class="panel" style="margin-top:16px"><div class="panel-body"><div class="eyebrow">CRITERIO DEL COMERCIANTE</div><p class="small muted">${esc(m.note)}</p><button data-action="craft-view" class="full">Consultar fabricación →</button></div></section><p class="support">El stock aleatorio es una propuesta de prueba: 8 fichas al azar, de 1 a 3 unidades, más el mínimo indicado. Se conserva hasta renovarlo. El carrito no descuenta existencias.</p></aside></div>`;
  renderMarketList();renderCart();
 }
 function renderMarketList(){const s=shop(),filtered=marketItems().filter(fits),pager=pagination(filtered.length);$('results').innerHTML=`<div class="table-head"><span>OBJETO / TIPO</span><span>UNIDAD</span><span>STOCK</span><span></span></div>${filtered.slice(page*18,page*18+18).map(e=>`<div class="item-row"><div><button class="item-name" data-action="inspect" data-id="${esc(e.id)}">${esc(e.name)}</button><small>${esc(e.category)}${e.scope.length?' · Homebrew':''}</small></div><span class="price">${esc(C.money(e.price))}</span><span class="stock ${s.mode==='random'&&!s.stock[e.id]?'pending':''}">${s.mode==='manual'?'DM decide':s.stock[e.id]?s.stock[e.id]+' disp.':e.craftMode!=='none'&&!C.craft(e,merchant(merchantId)).error?'A fabricar':'Sin stock'}</span><button class="add" data-action="cart-add" data-id="${esc(e.id)}" aria-label="Agregar ${esc(e.name)} a la compra">＋</button></div>`).join('')||'<div class="empty">No hay coincidencias. Podés crear el objeto que falta.</div>'}${pager}`;}
 function renderCart(){const s=shop(),items=available(),sum=C.total(cartLines(),items,merchantId==='temay'?s.discount:0);$('cart').innerHTML=`<div class="receipt"><div class="receipt-title">CANTIDADES Y COSTO FINAL</div>${cartLines().map(l=>{const e=items.find(e=>e.id===l.id);if(!e)return '';return `<div class="cart-line"><div class="line-top"><strong>${esc(e.name)}</strong><span class="price">${esc(C.money(e.price===null?null:Math.round(e.price*l.qty*100)/100))}</span></div><div class="line-bottom"><div class="qty"><button data-action="cart-minus" data-id="${esc(e.id)}" aria-label="Restar ${esc(e.name)}">−</button><input type="number" min="1" max="10000" value="${l.qty}" data-qty="${esc(e.id)}" aria-label="Cantidad de ${esc(e.name)}"><button data-action="cart-add" data-id="${esc(e.id)}" aria-label="Sumar ${esc(e.name)}">＋</button></div><button class="text-button" data-action="cart-remove" data-id="${esc(e.id)}">Quitar</button></div>${s.mode==='random'&&l.qty>(s.stock[e.id]||0)?'<small class="stock pending">Supera el stock · consultar al DM o fabricar</small>':''}</div>`;}).join('')||'<div class="empty">Tu compra está vacía.<br>Agregá objetos con el botón ＋.</div>'}${merchantId==='temay'?`<label style="margin-top:16px">Descuento decidido por el DM (%)<input id="discount" type="number" min="0" max="25" step="1" value="${s.discount}"></label>`:''}<div class="receipt-total"><span>Total${sum.pending?' conocido':''}</span><strong>${esc(C.money(sum.amount))}</strong></div>${sum.pending?`<p class="stock pending">${sum.pending} línea(s) con precio pendiente. El total está incompleto.</p>`:''}<button class="full" data-action="cart-export" ${cartLines().length?'':'disabled'}>↓ Exportar compra</button><button class="text-button full" data-action="cart-clear" ${cartLines().length?'':'disabled'}>Vaciar compra</button><p class="support">Solo consulta y cálculo. La compra no registra pedidos, fechas ni entregas.</p></div>`;}
 function renderLibrary(){
  const isHomebrew=view==='homebrew',items=(isHomebrew?db.entries.filter(e=>C.visible(e,db.campaign)):available()).filter(e=>view==='spells'?e.type==='spell':view==='rules'?e.type==='rule':true);
  const options=view==='library'||isHomebrew?`<select id="type-filter" aria-label="Filtrar por tipo"><option value="all">Todos los tipos</option>${Object.entries(types).map(([id,name])=>`<option value="${id}" ${filter===id?'selected':''}>${name}</option>`).join('')}</select>`:'';
  $('view').innerHTML=`${sourceNotice()}<div class="split"><section class="panel"><div class="panel-head"><h2>${isHomebrew?'Tus creaciones':'Contenido disponible'}</h2><span class="tag">${items.length} FICHAS</span></div><div class="toolbar"><input id="search" type="search" placeholder="Buscar por nombre, efecto o referencia…" value="${esc(query)}" aria-label="Buscar contenido">${options}</div><div id="results"></div></section><aside id="detail" class="panel detail"></aside></div>`;
  renderLibraryList();renderDetail();
 }
 function libraryItems(){return(view==='homebrew'?db.entries.filter(e=>C.visible(e,db.campaign)):available()).filter(e=>(view!=='spells'||e.type==='spell')&&(view!=='rules'||e.type==='rule')).filter(fits);}
 function renderLibraryList(){const items=libraryItems(),pager=pagination(items.length);$('results').innerHTML=items.slice(page*18,page*18+18).map(e=>`<div class="item-row" style="grid-template-columns:minmax(0,1fr) 95px"><div><button class="item-name" data-action="select" data-id="${esc(e.id)}">${esc(e.name)}</button><small>${esc(e.category)} · ${esc(e.origin)}</small></div><span class="tag">${esc(types[e.type])}</span></div>`).join('')+(!items.length?'<div class="empty">Todavía no hay contenido acá.<br>Creá una ficha o cambiá de campaña.</div>':'')+pager;}
 function detailHTML(e){if(!e)return '<div class="panel-body"><div class="big-symbol">▥</div><h2>Tu referencia,<br>a un clic.</h2><p class="muted small">Elegí una ficha para leerla, crear una variante o usarla en otra herramienta.</p><p class="support">Las fichas propias pueden ser globales o compartirse con las campañas que elijas.</p></div>';return `<div class="panel-body"><div class="eyebrow">${esc(types[e.type])} / ${esc(e.category)}</div><h2>${esc(e.name)}</h2><p><span class="pill">${e.scope.length?'CAMPAÑA':'GLOBAL'}</span> <span class="tag">${esc(e.status)}</span></p>${e.type==='item'?`<p class="price accent">${esc(C.money(e.price))}</p>`:''}<div class="detail-description">${esc(e.description)}</div>${e.attributes?`<details style="margin-top:16px"><summary class="small muted">Atributos y requisitos</summary><p class="detail-description">${esc(e.attributes)}</p></details>`:''}<div class="detail-source">${esc(e.origin)}${e.parent?'<br>Variante de: '+esc(entry(e.parent)?.name||e.parent):''}</div><div class="detail-actions"><button data-action="clone" data-id="${esc(e.id)}">Crear variante</button>${e.id.startsWith('custom:')?`<button data-action="edit" data-id="${esc(e.id)}">Editar</button>`:''}${e.type==='item'?`<button data-action="craft-item" data-id="${esc(e.id)}">Fabricación →</button>`:''}</div>${e.type==='item'&&e.craftMode==='none'?'<p class="support">Sin receta calculable. Podés definirla en una variante propia.</p>':''}</div>`;}
 function renderDetail(){if($('detail'))$('detail').innerHTML=detailHTML(selected?entry(selected):null);}
 function renderCraft(){
  const items=available().filter(e=>e.type==='item');if(!items.some(e=>e.id===craftId))craftId=items.find(e=>e.craftMode==='common'&&e.tool)?.id||items[0]?.id;
  const e=entry(craftId),m=merchant(craftMerchant),result=e?C.craft(e,m,craftQty):{error:'No hay objetos disponibles.'};
  $('view').innerHTML=`<div class="split"><section class="panel"><div class="panel-head"><h2>Consultar fabricación</h2><span class="pill">SIN GESTIÓN DE ENCARGOS</span></div><div class="panel-body"><div class="form-grid"><label>Quién fabrica<select id="craft-merchant">${merchantOptions(craftMerchant)}</select></label><label>Cantidad<input id="craft-qty" type="number" min="1" max="10000" value="${craftQty}"></label></div><label>Objeto<select id="craft-item">${items.map(i=>`<option value="${esc(i.id)}" ${i.id===craftId?'selected':''}>${esc(i.name)} · ${esc(C.money(i.price))}</option>`).join('')}</select></label><div class="calc-result">${result.error?`<h2>Faltan datos para calcular</h2><p class="muted small">${esc(result.error)}</p><button data-action="clone" data-id="${esc(craftId)}">Definir una variante propia</button>`:`<small class="eyebrow">INFORMACIÓN PARA EL DM</small><p>Entrega en <strong>${esc(result.days)} ${result.days===1?'día':'días'}</strong></p><div class="two"><div><small>Materiales · costo de fabricación</small><strong>${esc(C.money(result.materials))}</strong></div><div><small>Precio de compra · ${craftQty} unidad(es)</small><strong>${esc(C.money(e.price===null?null:Math.round(e.price*craftQty*100)/100))}</strong></div></div><p class="support">${esc(result.rule)}<br>Requiere ${esc(result.tool)}, competencia y materiales disponibles. El DM confirma las condiciones. No se añade un margen de venta automáticamente.</p>`}</div><p class="support">No se registra una fecha de entrega. Si creás un objeto nuevo, se guarda su ficha para futuros usos. Las reglas mágicas y de pergaminos todavía no tienen calculadora.</p></div></section><aside class="panel detail">${detailHTML(e)}</aside></div>`;
 }
 function renderLoot(){const pool=available().filter(e=>e.type==='item'&&e.loot),history=db.loot.filter(l=>l.campaign===db.campaign);$('view').innerHTML=`<div class="split"><section><div class="panel"><div class="panel-head"><h2>Sorteo del catálogo compartido</h2><span class="tag">${pool.length} ELEGIBLES</span></div><div class="panel-body"><div class="notice">Sorteo uniforme para probar la conexión entre módulos. No usa las tablas D100 ni las fórmulas de cofres del prototipo 1.2.</div><div class="form-grid"><label>Cantidad de selecciones<input id="loot-count" type="number" min="1" max="20" value="${lootCount}"></label><div style="align-self:end"><button class="primary full" style="margin:0" data-action="roll-loot">◇ Generar loot</button></div></div><button data-action="empty-loot">Sin loot · registrar resultado vacío</button></div></div><div style="margin-top:20px">${history.map(l=>`<section class="panel" style="margin-bottom:14px"><div class="panel-head"><h2>${l.items.length?'Recompensa':'Sin botín'}</h2><span class="muted small">${esc(new Date(l.date).toLocaleString('es-AR'))}</span></div><div class="panel-body">${l.items.map(i=>`<div class="cart-line"><strong>${esc(i.name)}</strong><span class="price" style="float:right">${esc(C.money(i.price))}</span><small class="muted" style="display:block">${esc(i.origin)}</small></div>`).join('')||'<p class="muted small">El DM decidió que este hallazgo o encuentro no deja loot.</p>'}</div></section>`).join('')||'<div class="empty">Los resultados de esta campaña aparecerán acá.</div>'}</div></section><aside class="panel"><div class="panel-body"><div class="eyebrow">MISMA BASE, DISTINTO USO</div><h2>Lo que creás<br>también puede salir.</h2><p class="muted small">Las fichas propias habilitadas para loot entran en el sorteo cuando están disponibles en la campaña activa.</p><p class="support">Los resultados guardan una copia de la ficha. Editarla después no cambia el loot anterior. Se conservan los últimos 100 resultados entre campañas.</p><a class="text-button" href="../../fuentes/loot-generator.html" target="_blank" rel="noopener">Abrir generador y D100 originales ↗</a></div></aside></div>`;}
 function renderCampaigns(){$('view').innerHTML=`<div class="notice">Selector y visibilidad funcionales. La lista de exclusiones admite activar/desactivar fichas; todavía no hay un motor general de efectos homebrew.</div><div class="cards">${db.campaigns.map(c=>`<section class="panel"><div class="card-top"><span class="pill">${c.id===db.campaign?'ACTIVA':'CAMPAÑA'}</span><span class="tag">${C.effective(all(),c.id,db.disabled).length} fichas</span></div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><button data-action="activate" data-id="${esc(c.id)}">${c.id===db.campaign?'Seguir en esta campaña':'Activar campaña →'}</button></section>`).join('')}</div><section class="panel" style="margin-top:20px"><div class="panel-head"><h2>Contenido propio en la campaña activa</h2></div><div class="panel-body">${db.entries.filter(e=>C.visible(e,db.campaign)).map(e=>`<label class="check"><input type="checkbox" data-enable="${esc(e.id)}" ${!(db.disabled[db.campaign]||[]).includes(e.id)?'checked':''}> ${esc(e.name)} <span class="muted">· ${e.scope.length?'Compartido con campañas elegidas':'Global'}</span></label>`).join('')||'<p class="muted small">Creá una ficha desde Homebrew para probar su disponibilidad y activación.</p>'}</div></section>`;}
 function openEditor(id=null,clone=false){
  const e=id?entry(id):null;const own=e&&!clone&&e.id.startsWith('custom:');
  $('editor-title').textContent=own?'Editar contenido':e?'Crear variante':'Crear contenido';$('entry-id').value=own?e.id:'';$('entry-parent').value=clone?e.id:e?.parent||'';
  const values={name:e?(clone?e.name+' · variante':e.name):'',type:e?.type||'item',category:e?.category||'Equipo',price:e?.price??'',description:e?.description||'',attributes:e?.attributes||'',craft:e?.craftMode==='healing'?'none':e?.craftMode||'none',tool:e?.tool||'',days:e?.days??'',materials:e?.materials??''};
  for(const [key,value]of Object.entries(values))$('entry-'+key).value=value;
  $('entry-magic').checked=!!e?.magic;$('entry-loot').checked=!!e?.loot;
  const scope=e?.scope||[];$('entry-global').checked=!scope.length;
  $('scope-options').innerHTML=db.campaigns.map(c=>`<label class="check"><input type="checkbox" name="scope" value="${esc(c.id)}" ${scope.includes(c.id)?'checked':''} ${!scope.length?'disabled':''}>${esc(c.name)}</label>`).join('');
  $('editor').showModal();$('entry-name').focus();
 }
 function info(title,body){$('info-title').textContent=title;$('info-body').innerHTML=body;$('info').showModal();}
 function campaignForm(){info('Nueva campaña',`<form id="campaign-form"><label>Nombre<input name="name" required maxlength="180"></label><label style="margin-top:14px">Descripción<textarea name="description" rows="3" maxlength="1000"></textarea></label><p class="muted small">Comparte la base global. Su contenido propio se elige desde Homebrew.</p><button class="primary full">Crear y activar</button></form>`);}
 function merchantForm(){info('Agregar comerciante',`<form id="merchant-form"><label>Nombre<input name="name" required maxlength="180"></label><label style="margin-top:14px">Campaña<select name="campaign"><option value="global">Global</option>${campaignOptions(db.campaign)}</select></label><fieldset><legend>Qué vende</legend>${['Armas','Armaduras','Herramientas','Equipo'].map(c=>`<label class="check"><input name="category" type="checkbox" value="${c}" checked>${c}</label>`).join('')}</fieldset><label>Herramientas para fabricar (una por línea)<textarea name="tools" rows="2" maxlength="1000" placeholder="Herramientas de herrero"></textarea></label><label style="margin-top:14px">Notas y reglas propias<textarea name="note" rows="3" maxlength="5000"></textarea></label><p class="muted small">Las notas son de consulta. No activan efectos automáticamente. El stock se define desde el mostrador.</p><button class="primary full">Guardar comerciante</button></form>`);}
 $('editor-form').onsubmit=event=>{
  event.preventDefault();const scope=$('entry-global').checked?[]:[...document.querySelectorAll('[name=scope]:checked')].map(n=>n.value);if(!$('entry-global').checked&&!scope.length){toast('Elegí al menos una campaña o disponibilidad global.');return;}
  const get=k=>$('entry-'+k).value.trim(),number=k=>get(k)===''?null:Number(get(k));
  const data={id:get('id')||'custom:'+C.uid(),name:get('name'),type:get('type'),category:get('category')||types[get('type')],description:get('description'),attributes:get('attributes'),price:number('price'),magic:$('entry-magic').checked,loot:$('entry-loot').checked&&get('type')==='item',scope,origin:'Contenido propio · homebrew',status:'Creación del DM',parent:get('parent'),craftMode:get('craft'),tool:get('tool'),days:number('days'),materials:number('materials')};
  if(data.magic&&data.craftMode==='common'){toast('Un objeto mágico necesita una receta propia; no usa fabricación común.');return;}
  if(data.craftMode==='manual'&&(!data.tool||!data.days||data.materials===null)){toast('La receta propia necesita herramienta, días y materiales.');return;}
  try{const next=structuredClone(db),index=next.entries.findIndex(e=>e.id===data.id);if(index<0)next.entries.push(data);else next.entries[index]=data;C.validate(next);db=next;save();$('editor').close();selected=data.id;render();toast('Ficha guardada en la biblioteca compartida.');}catch(err){toast(err.message);}
 };
 $('entry-global').onchange=()=>document.querySelectorAll('[name=scope]').forEach(n=>n.disabled=$('entry-global').checked);
 $('campaign').onchange=()=>{db.campaign=$('campaign').value;merchantId='general';craftMerchant='general';selected=null;query='';page=0;save();render();};
 $('create').onclick=()=>view==='market'?merchantForm():view==='campaigns'?campaignForm():openEditor();
 $('backup').onclick=()=>download('botin-prototipo-respaldo.json',JSON.stringify(db,null,2));
 $('restore').onclick=()=>$('backup-file').click();
 $('backup-file').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>15000000)throw Error('El respaldo supera 15 MB.');const next=C.validate(JSON.parse(await file.text()));if(!confirm('¿Reemplazar los datos de este prototipo? Exportá antes lo que quieras conservar. No afecta BOTÍN.EXE 1.2.'))return;db=next;blocked=false;merchantId='general';query='';selected=null;save();render();toast('Respaldo importado.');}catch(err){toast('No se importó: '+err.message);}};
 $('credits').onclick=()=>info('Créditos y fuentes',`<p>Idea, dirección y reglas propias: <strong>Sarten / Sebas</strong>.</p><p>Diseño e implementación en colaboración: <strong>Reldor Dawncaller · ChatGPT / Codex</strong>. Prototipo BOTÍN.EXE anterior realizado con Claude y aportado por Sarten.</p><hr><p class="small">Esta obra incluye material procedente del documento de referencia del sistema 5.2.1 (“SRD 5.2.1”) de Wizards of the Coast LLC, disponible en <a href="https://www.dndbeyond.com/srd" target="_blank" rel="noopener">dndbeyond.com/srd</a>. La licencia sobre el SRD 5.2.1 se concede de acuerdo con la licencia internacional de atribución/reconocimiento 4.0 de Creative Commons, disponible en <a href="https://creativecommons.org/licenses/by/4.0/legalcode" target="_blank" rel="noopener">CC BY 4.0</a>.</p><p class="small muted">Adaptaciones de esta prueba: extracción estructurada desde el Markdown local, traducción parcial de nombres y presentación en fichas. Textos originales en inglés; cotejo completo con el PDF español pendiente. No se importaron las tablas ni textos exclusivos del Manual del DM. Las reglas de comerciantes proceden de los documentos activos de Romanance, de alcance exclusivo para esa campaña.</p><p class="small muted">Prototipo 0.1, propuesta de interfaz. No valida contenido, balance ni la distribución comercial de todo el proyecto. Nombre definitivo y aviso de derechos propios pendientes.</p>`);
 document.addEventListener('submit',event=>{if(event.target.id==='campaign-form'){event.preventDefault();const form=new FormData(event.target),name=String(form.get('name')).trim();if(!name)return;const c={id:'campaign-'+C.uid(),name,description:String(form.get('description')).trim()};db.campaigns.push(c);db.campaign=c.id;merchantId='general';save();$('info').close();render();toast('Campaña creada.');}if(event.target.id==='merchant-form'){event.preventDefault();const form=new FormData(event.target),name=String(form.get('name')).trim(),categories=form.getAll('category');if(!name||!categories.length){toast('Indicá nombre y al menos una categoría.');return;}const m={id:'merchant-'+C.uid(),name,scope:form.get('campaign')==='global'?[]:[String(form.get('campaign'))],categories,tools:String(form.get('tools')).split('\n').map(s=>s.trim()).filter(Boolean),note:String(form.get('note')).trim(),forge:false};db.merchants.push(m);merchantId=m.id;save();$('info').close();render();toast('Comerciante guardado.');}});
 document.addEventListener('input',event=>{const t=event.target;if(t.id==='search'){query=t.value;page=0;view==='market'?renderMarketList():renderLibraryList();}if(t.dataset.qty){const qty=Number(t.value);if(Number.isInteger(qty)&&qty>=1&&qty<=10000){const line=shop().cart.find(l=>l.id===t.dataset.qty);if(line){line.qty=qty;save();const sum=C.total(cartLines(),available(),merchantId==='temay'?shop().discount:0);document.querySelector('.receipt-total strong').textContent=C.money(sum.amount);}}}});
 document.addEventListener('change',event=>{const t=event.target;if(t.dataset.qty){renderCart();return;}if(t.id==='merchant'){merchantId=t.value;query='';page=0;renderMarket();}if(t.id==='type-filter'){filter=t.value;page=0;renderLibraryList();}if(t.id==='stock-mode'){shop().mode=t.value;save();renderMarket();}if(t.id==='stock-floor'){if(!t.checkValidity()){t.reportValidity();return;}shop().floor=Number(t.value);save();}if(t.id==='discount'){if(!t.checkValidity()){t.reportValidity();return;}shop().discount=Number(t.value);save();renderCart();}if(t.id==='craft-merchant'){craftMerchant=t.value;renderCraft();}if(t.id==='craft-item'){craftId=t.value;renderCraft();}if(t.id==='craft-qty'){if(!t.checkValidity()){t.reportValidity();return;}craftQty=Number(t.value);renderCraft();}if(t.id==='loot-count'){if(!t.checkValidity()){t.reportValidity();return;}lootCount=Number(t.value);}if(t.dataset.enable){const ids=new Set(db.disabled[db.campaign]||[]);t.checked?ids.delete(t.dataset.enable):ids.add(t.dataset.enable);db.disabled[db.campaign]=[...ids];save();renderCampaigns();}});
 document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}if(b.dataset.view){navigate(b.dataset.view);return;}const action=b.dataset.action,id=b.dataset.id;if(!action)return;
  if(action==='prev'||action==='next'){page+=action==='prev'?-1:1;view==='market'?renderMarketList():renderLibraryList();}
  if(action==='select'){selected=id;renderDetail();}
  if(action==='inspect'){info(entry(id).name,detailHTML(entry(id)));}
  if(action==='clone'||action==='edit'){if($('info').open)$('info').close();openEditor(id,action==='clone');}
  if(action==='craft-item'){if($('info').open)$('info').close();craftId=id;craftMerchant=merchantId;navigate('craft');}
  if(action==='craft-view'){craftMerchant=merchantId;navigate('craft');}
  if(action==='cart-add'){const s=shop(),e=available().find(e=>e.id===id);if(!e||!marketItems().some(e=>e.id===id))return;const line=s.cart.find(l=>l.id===id);if(line){if(line.qty>=10000)return;line.qty++;}else s.cart.push({id,qty:1});save();renderCart();toast('Agregado a la compra.');}
  if(action==='cart-minus'){const s=shop(),line=s.cart.find(l=>l.id===id);if(line){line.qty--;s.cart=s.cart.filter(l=>l.qty>0);save();renderCart();}}
  if(action==='cart-remove'){shop().cart=shop().cart.filter(l=>l.id!==id);save();renderCart();}
  if(action==='cart-clear'){if(confirm('¿Vaciar esta compra? Las fichas y el stock se conservan.')){shop().cart=[];save();renderCart();}}
  if(action==='cart-export'){const s=shop();download('compra-'+merchantId+'.json',JSON.stringify({campaign:db.campaigns.find(c=>c.id===db.campaign).name,merchant:merchant(merchantId).name,items:cartLines().map(l=>({...structuredClone(entry(l.id)),quantity:l.qty})),discount:merchantId==='temay'?s.discount:0,total:C.total(cartLines(),available(),merchantId==='temay'?s.discount:0)},null,2));}
  if(action==='restock'){shop().stock=C.stock(marketItems(),shop().floor);shop().mode='random';save();renderMarket();toast('Stock renovado y guardado.');}
  if(action==='activate'){db.campaign=id;merchantId='general';selected=null;save();render();}
  if(action==='roll-loot'||action==='empty-loot'){const pool=available().filter(e=>e.type==='item'&&e.loot);if(action==='roll-loot'&&!pool.length){toast('No hay objetos habilitados.');return;}const items=action==='empty-loot'?[]:Array.from({length:lootCount},()=>{const e=pool[Math.floor(Math.random()*pool.length)];return{id:e.id,name:e.name,description:e.description,origin:e.origin,price:e.price};});db.loot.unshift({id:C.uid(),campaign:db.campaign,date:new Date().toISOString(),items});db.loot=db.loot.slice(0,100);save();renderLoot();toast(items.length?'Loot generado.':'Resultado sin botín registrado.');}
 });
 function refreshCraftCalculation(){const e=entry(craftId),result=C.craft(e,merchant(craftMerchant),craftQty),panel=document.querySelector('.calc-result');if(!panel)return;panel.innerHTML=result.error?`<h2>Faltan datos para calcular</h2><p class="muted small">${esc(result.error)}</p>`:`<small class="eyebrow">INFORMACIÓN PARA EL DM</small><p>Entrega en <strong>${esc(result.days)} ${result.days===1?'día':'días'}</strong></p><div class="two"><div><small>Materiales · costo de fabricación</small><strong>${esc(C.money(result.materials))}</strong></div><div><small>Precio de compra · ${craftQty} unidad(es)</small><strong>${esc(C.money(e.price===null?null:Math.round(e.price*craftQty*100)/100))}</strong></div></div><p class="support">${esc(result.rule)}<br>Requiere ${esc(result.tool)}, competencia y materiales disponibles. El DM confirma las condiciones. No se añade un margen de venta automáticamente.</p>`;}
 document.addEventListener('input',event=>{const t=event.target;if(t.dataset.qty&&t.checkValidity()){const e=entry(t.dataset.qty),price=t.closest('.cart-line').querySelector('.line-top .price');price.textContent=C.money(e.price===null?null:Math.round(e.price*Number(t.value)*100)/100);}if(t.id==='craft-qty'&&t.checkValidity()){craftQty=Number(t.value);refreshCraftCalculation();}if(t.id==='loot-count'&&t.checkValidity())lootCount=Number(t.value);if(t.id==='stock-floor'&&t.checkValidity()){shop().floor=Number(t.value);save();}if(t.id==='discount'&&t.checkValidity()){shop().discount=Number(t.value);save();document.querySelector('.receipt-total strong').textContent=C.money(C.total(cartLines(),available(),shop().discount).amount);}});
 if(blocked){$('save-status').textContent='⚠ Datos previos protegidos';toast('No se pudieron leer los datos guardados. No se sobrescribirán. Podés importar un respaldo válido.');}
 window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(labels[next]&&next!==view)navigate(next);});
 const requested=location.hash.slice(1);view=labels[requested]?requested:'market';render();
})();
